<?php
declare(strict_types=1); require_once __DIR__ . '/../config/api.php';
if($_SERVER['REQUEST_METHOD']!=='POST')respond(['success'=>false,'message'=>'Method not allowed'],405);$u=requireUser($pdo);$d=jsonInput();$vacancyId=(int)($d['vacancy_id']??0);if($vacancyId<=0)respond(['success'=>false,'message'=>'vacancy_id is required'],422);
$s=$pdo->prepare("SELECT id,openings_count FROM vacancies WHERE id=? AND status='published' AND deleted_at IS NULL AND (closing_at IS NULL OR closing_at>UTC_TIMESTAMP()) LIMIT 1");$s->execute([$vacancyId]);$v=$s->fetch(PDO::FETCH_ASSOC);if(!$v)respond(['success'=>false,'message'=>'Job is not available'],404);
$check=$pdo->prepare('SELECT id,status FROM applications WHERE vacancy_id=? AND user_id=? LIMIT 1');$check->execute([$vacancyId,$u['user_id']]);$existing=$check->fetch(PDO::FETCH_ASSOC);if($existing)respond(['success'=>false,'message'=>'You have already applied for this vacancy','data'=>['application_id'=>(int)$existing['id'],'status'=>$existing['status']]],409);
$stmt=$pdo->prepare("INSERT INTO applications(vacancy_id,user_id,status) VALUES(?,?, 'applied')");$stmt->execute([$vacancyId,$u['user_id']]);$id=(int)$pdo->lastInsertId();respond(['success'=>true,'message'=>'Application submitted successfully','data'=>['application_id'=>$id,'status'=>'applied']],201);
